const base=new URL('./assets/admin-2022/',import.meta.url);let catalogPromise;const cache=new Map();
export function adminCatalog(){return catalogPromise??=(fetch(new URL('index.json',base)).then(r=>{if(!r.ok)throw Error('Administrative boundary list could not be loaded.');return r.json();}).catch(e=>{catalogPromise=null;throw e;}));}
export function cleanAdmin(value){if(value?.type!=='admin-2022'||!['province','district','sector'].includes(value.level)||typeof value.id!=='string'||!/^\d{1,8}$/.test(value.id))throw Error('Invalid administrative boundary. Select it again.');return {type:'admin-2022',level:value.level,id:value.id};}
export function adminOptions(catalog,level,provinceId='',districtId=''){return catalog[level+'s'].filter(r=>(!provinceId||level==='province'||r.provinceId===provinceId)&&(!districtId||level!=='sector'||r.districtId===districtId)).sort((a,b)=>a.name.localeCompare(b.name));}
export async function resolveAdmin(value){const scope=cleanAdmin(value),catalog=await adminCatalog(),record=catalog[scope.level+'s'].find(r=>r.id===scope.id);if(!record)throw Error('Selected administrative boundary is unavailable.');if(!cache.has(record.file))cache.set(record.file,(async()=>{const r=await fetch(new URL(record.file+'.gz',base));if(!r.ok)throw Error('Administrative polygon could not be loaded.');const stream=r.body.pipeThrough(new DecompressionStream('gzip'));return JSON.parse(await new Response(stream).text());})().catch(e=>{cache.delete(record.file);throw e;}));const geometry=(await cache.get(record.file))[record.id];if(!geometry)throw Error('Administrative polygon is missing.');return {scope:{...scope,label:record.name+' ('+scope.level+')'},geometry,record,catalog};}
